#!/usr/bin/env python3
"""Isolated Chromium QA. Uses only generated HTML and synthetic inputs; never controls the user's desktop."""
from __future__ import annotations
import argparse, asyncio, json, time
from pathlib import Path
from playwright.async_api import async_playwright
ROOT=Path(__file__).resolve().parents[1]
RESULTS=[]
(ROOT/'previews').mkdir(parents=True,exist_ok=True)
async def check(name, condition, detail=''):
    ok=bool(condition)
    RESULTS.append({'name':name,'passed':ok,'detail':detail})
    if not ok: raise AssertionError(name+': '+detail)
async def main(group):
 async with async_playwright() as p:
  browser=await p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
  context=await browser.new_context(viewport={'width':1600,'height':1000},device_scale_factor=1)
  page=await context.new_page();errors=[];requests=[]
  page.on('pageerror',lambda e:errors.append(str(e)))
  page.on('request',lambda r:requests.append(r.url))
  await page.set_content((ROOT/'standalone.html').read_text(),wait_until='load');await page.wait_for_function('window.demo?.ready')
  async def reset():
   await page.evaluate('demo.reset()');await page.wait_for_timeout(350)
  async def task(kind,fixture='success'):
   await page.select_option('#fixture',fixture)
   await page.evaluate('(k)=>{void demo.runTask(k)}',kind)
   await page.wait_for_function('demo.state.task === null',timeout=7000)
   await page.wait_for_timeout(350)
  async def draw(kind='rect'):
   await page.locator(f'[data-action="{kind}"]').click()
   r=await page.locator('#marks').bounding_box();x=r['x']+r['width']*.15;y=r['y']+r['height']*.58
   await page.mouse.move(x,y);await page.mouse.down();await page.mouse.move(x+150,y+60,steps=8);await page.mouse.up();await page.wait_for_timeout(300)
  await reset()
  if group=='core':
   await check('七个场景与完整启动',await page.locator('[data-scene]').count()==7)
   before=await page.locator('[data-action="rect"]').bounding_box()
   await page.locator('[data-action="rect"]').hover();await page.wait_for_timeout(350)
   after=await page.locator('[data-action="rect"]').bounding_box()
   await check('临近响应不移动语义命中盒',before==after)
   await check('悬停不改变工具选择',await page.evaluate('demo.state.tool')=='select')
   await check('材质实际发生形变',await page.locator('[data-action="rect"] .face').evaluate('e=>getComputedStyle(e).transform')!='none')
   await page.locator('[data-action="select"]').hover();await page.wait_for_timeout(70)
   await page.locator('[data-action="rect"]').hover();await page.wait_for_timeout(35)
   await check('跨相邻按钮出现临时液桥',await page.locator('#liquidLinks path').count()>0)
   await page.mouse.move(10,10);await page.wait_for_timeout(1300)
   a=await page.evaluate('demo.engine.frames');await page.wait_for_timeout(300);b=await page.evaluate('demo.engine.frames')
   await check('离开并停稳后 RAF 休眠',a==b,f'{a} -> {b}')
   await check('静止后液桥清除',await page.locator('#liquidLinks path').count()==0)
   await draw();await check('手绘矩形单次提交',await page.evaluate('demo.state.marks.length===1&&demo.state.history.length===2'))
   await page.locator('[data-action="undo"]').click();await check('撤销绘制',await page.evaluate('demo.state.marks.length')==0)
   await page.locator('[data-action="redo"]').click();await check('重做绘制',await page.evaluate('demo.state.marks.length')==1)
   await reset();await draw('arrow');await check('箭头绘制',await page.evaluate('demo.state.marks[0].type')=='arrow')
   await reset();await draw('cover');await check('遮盖为不透明实色',await page.locator('#marks .annotation').get_attribute('fill-opacity')=='1')
   await reset();await page.locator('[data-action="text"]').click();r=await page.locator('#marks').bounding_box();await page.mouse.click(r['x']+100,r['y']+150)
   await page.locator('#newText').fill('液态共生');await page.locator('#newText').press('Enter');await page.wait_for_timeout(250)
   await check('文字定位与提交',await page.evaluate('demo.state.marks[0].text')=='液态共生')
   await reset();await page.locator('[data-action="rect"]').click();r=await page.locator('#marks').bounding_box();await page.mouse.move(r['x']+100,r['y']+100);await page.mouse.down();await page.mouse.move(r['x']+250,r['y']+160);await page.keyboard.press('Escape');await page.mouse.up()
   await check('Esc 取消草稿不写历史',await page.evaluate('demo.state.marks.length===0&&demo.state.history.length===1'))
   await reset();await page.locator('[data-action="beauty"]').click();await page.wait_for_timeout(320)
   pr=await page.locator('#panel').bounding_box();rr=await page.locator('#rail').bounding_box();overlap=max(0,min(pr['x']+pr['width'],rr['x']+rr['width'])-max(pr['x'],rr['x']))*max(0,min(pr['y']+pr['height'],rr['y']+rr['height'])-max(pr['y'],rr['y']))
   await check('默认属性卡不遮挡动作轨',overlap==0,str(overlap))
   await page.locator('[data-preset="mist"]').click();await check('美化预设实际更新',await page.evaluate('demo.state.style.preset')=='mist')
   await page.locator('#newCapture').click();sr=await page.locator('#stage').bounding_box();await page.mouse.move(sr['x']+130,sr['y']+90);await page.mouse.down();await page.mouse.move(sr['x']+530,sr['y']+310,steps=8);await page.mouse.up();await page.wait_for_timeout(350)
   await check('手动框选回到可编辑态',await page.evaluate('demo.state.phase==="editing"&&demo.state.rect.w===400&&demo.state.rect.h===220'))
   await reset();await page.screenshot(path=str(ROOT/'previews/01-capture.png'),full_page=True)
  if group=='tasks':
   await task('complete','failure');await check('复制失败保留编辑现场',await page.evaluate('demo.state.phase')=='editing' and await page.locator('#capture').is_visible())
   await check('失败提示不会提前成功', '失败' in await page.locator('#toast').text_content())
   await task('complete','stale');await check('过期完成结果不隐藏',await page.evaluate('demo.state.phase')=='editing' and '过期' in await page.locator('#toast').text_content())
   await page.select_option('#fixture','slow');await page.evaluate('void demo.runTask("complete")');await page.wait_for_timeout(150);await page.locator('#taskCancel').click();await page.wait_for_timeout(150)
   await check('慢完成可取消',await page.evaluate('demo.state.task===null&&demo.state.phase==="editing"'))
   await task('ocr');await check('OCR 合成结果回填',await page.evaluate('demo.state.source.length')>20)
   await task('text');await check('译文不覆盖原文',await page.evaluate('demo.state.source.includes("workspace")&&demo.state.translation.includes("安静")'))
   source=await page.evaluate('demo.state.source');await task('ocr','empty');await check('空结果保留已校对原文',await page.evaluate('demo.state.source')==source)
   await task('ocr','partial');await check('部分失败提供重试',await page.locator('#toast').get_by_text('重试',exact=True).is_visible())
   await page.locator('#toast').get_by_text('重试',exact=True).click();await page.wait_for_function('demo.state.task===null',timeout=5000)
   await reset();await task('image');await check('图片翻译提供独立阅读入口',await page.locator('[data-action="reader"]').is_visible())
   await check('原位译文图层存在',await page.locator('#translationLayer .translated-text').count()==2)
   await page.locator('[data-action="reader"]').click();await page.wait_for_timeout(250);await page.locator('#readCompare').click();await page.locator('#fontUp').click()
   await check('阅读对照与字号',await page.evaluate('demo.state.compare&&demo.state.readerFont===20'))
   await page.screenshot(path=str(ROOT/'previews/05-reader.png'),full_page=True)
   await page.locator('#readerClose').click();await page.locator('[data-action="undo"]').click();await check('图片译文单步撤销',not await page.evaluate('demo.state.translated'))
   await reset();await task('complete');await page.wait_for_function('demo.state.phase==="hidden"',timeout=3000)
   await check('成功确认后退出并清理文档',await page.evaluate('demo.state.marks.length===0') and await page.locator('#resting').is_visible())
   await page.screenshot(path=str(ROOT/'previews/06-complete.png'),full_page=True)
   await reset();await page.select_option('#fixture','slow');await page.evaluate('void demo.runTask("image")');await page.wait_for_timeout(140);await page.evaluate('demo.newCapture(true)');new_id=await page.evaluate('demo.state.documentId');await page.wait_for_timeout(4200)
   await check('连续截图拒绝旧任务回填',await page.evaluate('demo.state.documentId')==new_id and not await page.evaluate('demo.state.translated') and await page.evaluate('demo.state.phase')=='editing')
  if group=='system':
   await page.locator('#reduceMotion').check();await page.locator('[data-action="rect"]').hover();await page.wait_for_timeout(250)
   await check('减少动态关闭位移和 RAF',await page.evaluate('demo.engine.raf===0') and await page.locator('[data-action="rect"] .face').evaluate('e=>getComputedStyle(e).transform')=='none')
   await page.locator('#reduceMotion').uncheck();await page.emulate_media(reduced_motion='reduce');await page.wait_for_timeout(100)
   await check('系统减少动态不可被开关覆盖',await page.locator('body').evaluate('e=>e.classList.contains("reduced")'))
   await page.emulate_media(reduced_motion='no-preference');await page.locator('#economy').check();await page.locator('[data-action="select"]').hover();await page.locator('[data-action="rect"]').hover();await page.wait_for_timeout(50)
   await check('低开销禁用液桥',await page.locator('#liquidLinks path').count()==0)
   await page.locator('#economy').uncheck();await page.evaluate('demo.openSettings("services")');await page.wait_for_timeout(300)
   await check('原生设置使用浏览器模拟模态',await page.locator('[role="dialog"]').is_visible() and await page.locator('.shell').evaluate('e=>e.inert'))
   await page.locator('#testService').click();await page.wait_for_timeout(800);await check('服务测试明确无真实连接','没有访问' in await page.locator('#settingsMessage').text_content())
   await page.screenshot(path=str(ROOT/'previews/07-settings.png'),full_page=True)
   await page.locator('[data-settings="updates"]').click();await page.locator('#checkUpdate').click();await page.locator('#downloadUpdate').click();await page.wait_for_timeout(220);await page.locator('#cancelUpdate').click();await check('更新下载取消恢复按钮',not await page.locator('#downloadUpdate').is_disabled())
   await page.keyboard.press('Escape');await check('Esc 仅关闭模态',await page.locator('#modalRoot').is_hidden() and await page.evaluate('demo.state.phase')=='editing')
   await page.locator('[data-scene="components"]').click();await page.wait_for_timeout(200)
   await check('基础组件页面可操作',await page.locator('.component-card').count()==5)
   await page.screenshot(path=str(ROOT/'previews/08-components.png'),full_page=True)
   await page.locator('#componentTerms').click();await check('条款默认未同意',await page.locator('#acceptTerms').is_disabled());await page.locator('#consent').check();await check('主动同意才能继续',not await page.locator('#acceptTerms').is_disabled());await page.keyboard.press('Escape')
   await reset();await page.evaluate('demo.openPanel("history")');await page.wait_for_timeout(300);await page.locator('[data-record="0"] [data-delete]').click();await page.locator('#confirmCancel').click();await check('删除确认取消保留记录',await page.locator('[data-record]').count()==3)
   await reset()
   for width,height in [(1024,900),(720,900),(390,844)]:
    await page.set_viewport_size({'width':width,'height':height});await page.wait_for_timeout(500)
    await check(f'{width}px 无页面横向溢出',await page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
    await check(f'{width}px 完成按钮可达',await page.locator('[data-action="complete"]').is_visible())
    # Open via runtime to test layout independently of scrolling a hidden toolbar tool.
    await page.evaluate('demo.openPanel("beauty",document.querySelector("[data-action=beauty]"))');await page.wait_for_timeout(300)
    pr=await page.locator('#panel').bounding_box();rr=await page.locator('#rail').bounding_box();overlap=max(0,min(pr['x']+pr['width'],rr['x']+rr['width'])-max(pr['x'],rr['x']))*max(0,min(pr['y']+pr['height'],rr['y']+rr['height'])-max(pr['y'],rr['y']))
    await check(f'{width}px 浮卡避开完成轨',overlap<.1,str(overlap))
    await page.screenshot(path=str(ROOT/f'previews/09-responsive-{width}.png'),full_page=True)
    await page.evaluate('demo.command("close-panel")');await page.wait_for_timeout(250)
  await check('无 JavaScript 异常',not errors,str(errors))
  await check('无外部网络请求',not requests,str(requests))
  await browser.close()
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--group',choices=['core','tasks','system'],default='core');a=parser.parse_args()
 try:asyncio.run(main(a.group))
 finally:
  path=ROOT/'tests'/f'result-{a.group}.json';path.write_text(json.dumps({'group':a.group,'environment':'headless Chromium / Linux / synthetic content','results':RESULTS},ensure_ascii=False,indent=2));print(path);print(json.dumps(RESULTS,ensure_ascii=False,indent=2))
